(* [comment removed for export] *)
#[local] Instance ap_fxd : FPState | 100 := mkFP bvmap_empty (Z_to_bv 32 0).

Section Segs.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Definition ap_rds (M : word -> option byte) (kx kf ls W h : Z) (linesf datak : Z -> Z) : Prop :=
  (forall v, (0 <= v < 256)%Z -> exists k, rdn SEGS M (Z_to_bv 64 (kx + 4 * v)) 4 = Some (Z_to_le_bytes 4 k) /\ (0 <= k <= 8)%Z) /\
  (forall v, (0 <= v < 256)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (kf + 4 * v)) 4 = Some bs) /\
  (forall k, (0 <= k < 10)%Z -> rdn SEGS M (Z_to_bv 64 (ls + 8 * k)) 8 = Some (Z_to_le_bytes 8 (linesf k))) /\
  (forall k i, (0 <= k < 10)%Z -> (0 <= i < h)%Z -> rdn SEGS M (Z_to_bv 64 (linesf k + 8 * i)) 8 = Some (Z_to_le_bytes 8 (datak k + W * i))) /\
  (forall k p, (0 <= k < 10)%Z -> (datak k <= p < datak k + W * h)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) /\
  (forall k, (0 <= k < 10)%Z -> (0 <= linesf k)%Z /\ (linesf k + 8 * h <= 2 ^ 47)%Z /\ (datak k mod 4 = 0)%Z /\ (4096 <= datak k)%Z /\ (datak k + W * h <= 2 ^ 47)%Z).

Definition APL : list reg := [5; 6; 11; 12; 14; 15; 16; 17]%bv.
(* [comment removed for export] *)
Definition ap_fp (fr fr' : bvmap 5 word) : Prop :=
  forall r : reg, r <> 10%bv -> r <> 11%bv -> r <> 12%bv -> r <> 13%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r.

(* [comment removed for export] *)
Lemma ap_px : forall fr0 regs0 fr cs regs (M : word -> option byte) (s kx kf ls W h w i j rs rd : Z) (linesf datak : Z -> Z),
  frm_zero cs -> (4096 + 96 <= s <= 2 ^ 47)%Z -> (W mod 4 = 0)%Z -> (0 <= j < w)%Z -> (w <= W)%Z -> (W <= 80000)%Z -> (0 <= i < h)%Z -> (h <= 20000)%Z ->
  (rs mod 4 = 0)%Z -> (4096 <= rs)%Z -> (rs + W <= 2 ^ 47)%Z -> (rd mod 4 = 0)%Z -> (4096 <= rd)%Z -> (rd + W <= 2 ^ 47)%Z -> (rd + W <= s - 96 \/ s <= rd)%Z ->
  (4096 <= kx)%Z -> (kx + 1024 <= 2 ^ 47)%Z -> (4096 <= kf)%Z -> (kf + 1024 <= 2 ^ 47)%Z -> (4096 <= ls)%Z -> (ls + 80 <= 2 ^ 47)%Z ->
  (forall p, (rs <= p < rs + W)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) ->
  ap_rds M kx kf ls W h linesf datak ->
  (forall p, (rd <= p < rd + W)%Z -> store_ok SEGS M (Z_to_bv 64 p) 1 = true) ->
  rdn SEGS M (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 w) ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 11 = Z_to_bv 64 j -> getr regs 12 = Z_to_bv 64 j -> getr regs 13 = Z_to_bv 64 (8 * i) ->
  getr regs 14 = Z_to_bv 64 (rs + j) -> getr regs 15 = Z_to_bv 64 (rd + j) -> getr regs 22 = Z_to_bv 64 1 ->
  getr regs 23 = Z_to_bv 64 kx -> getr regs 24 = Z_to_bv 64 kf -> getr regs 25 = Z_to_bv 64 ls ->
  regs_agree (fun r => In r APL) regs0 regs -> ap_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e13c : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2e1d4 : word) M' rom /\ frm_zero cs' /\
                (exists p bs, (rd <= p < rd + W)%Z /\ length bs = 1%nat /\ M' = wbytes M (Z_to_bv 64 p) bs) /\
                getr regs' 16 = Z_to_bv 64 w /\ getr regs' 11 = Z_to_bv 64 (j + 1) /\ getr regs' 12 = Z_to_bv 64 (j + 1) /\
                getr regs' 14 = Z_to_bv 64 (rs + (j + 1)) /\ getr regs' 15 = Z_to_bv 64 (rd + (j + 1)) /\
                regs_agree (fun r => In r APL) regs0 regs' /\ ap_fp fr0 fr').
Proof.
