Definition APJ : list reg := [5; 6; 11; 12; 14; 15; 16; 17]%bv.
(* [comment removed for export] *)
Lemma ap_jloop : forall (n : nat) fr0 regs0 fr cs regs (Mj M : word -> option byte) (s kx kf ls W h w i j rs rd : Z) (linesf datak : Z -> Z),
  Z.of_nat n = (w - j)%Z -> (0 <= j < w)%Z -> frm_zero cs -> rinv [(rd, W)] Mj M ->
  (4096 + 96 <= s <= 2 ^ 47)%Z -> (W mod 4 = 0)%Z -> (w <= W)%Z -> (W <= 80000)%Z -> (0 <= i < h)%Z -> (h <= 20000)%Z ->
  (rs mod 4 = 0)%Z -> (4096 <= rs)%Z -> (rs + W <= 2 ^ 47)%Z -> (rd mod 4 = 0)%Z -> (4096 <= rd)%Z -> (rd + W <= 2 ^ 47)%Z -> (rd + W <= s - 96 \/ s <= rd)%Z ->
  (4096 <= kx)%Z -> (kx + 1024 <= 2 ^ 47)%Z -> (4096 <= kf)%Z -> (kf + 1024 <= 2 ^ 47)%Z -> (4096 <= ls)%Z -> (ls + 80 <= 2 ^ 47)%Z ->
  store_ok SEGS Mj (Z_to_bv 64 rs) (Z.to_nat W) = true -> store_ok SEGS Mj (Z_to_bv 64 rd) (Z.to_nat W) = true ->
  ap_rds Mj kx kf ls W h linesf datak -> ap_apart rd W kx kf ls W h linesf datak ->
  rdn SEGS Mj (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 w) ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 11 = Z_to_bv 64 j -> getr regs 12 = Z_to_bv 64 j -> getr regs 13 = Z_to_bv 64 (8 * i) ->
  getr regs 14 = Z_to_bv 64 (rs + j) -> getr regs 15 = Z_to_bv 64 (rd + j) -> getr regs 22 = Z_to_bv 64 1 ->
  getr regs 23 = Z_to_bv 64 kx -> getr regs 24 = Z_to_bv 64 kf -> getr regs 25 = Z_to_bv 64 ls ->
  regs_agree (fun r => In r APJ) regs0 regs -> ap_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e13c : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2e1d8 : word) M' rom /\ frm_zero cs' /\ rinv [(rd, W)] Mj M' /\
                getr regs' 16 = Z_to_bv 64 w /\ regs_agree (fun r => In r APJ) regs0 regs' /\ ap_fp fr0 fr').
