Lemma ap_iloop : forall (n : nat) fr0 regs0 fr cs regs (M0 M : word -> option byte) (s kx kf ls W h w i datas dd : Z) (linesf datak : Z -> Z),
  Z.of_nat n = (h - i)%Z -> (0 <= i < h)%Z -> frm_zero cs -> rinv [(dd, (W * h)%Z)] M0 M ->
  (4096 + 96 <= s <= 2 ^ 47)%Z -> (W mod 4 = 0)%Z -> (1 <= w)%Z -> (w <= W)%Z -> (W <= 80000)%Z -> (h <= 20000)%Z ->
  (datas mod 4 = 0)%Z -> (4096 <= datas)%Z -> (datas + W * h <= 2 ^ 47)%Z -> (dd mod 4 = 0)%Z -> (4096 <= dd)%Z -> (dd + W * h <= 2 ^ 47)%Z -> (dd + W * h <= s - 96 \/ s <= dd)%Z ->
  (4096 <= kx)%Z -> (kx + 1024 <= 2 ^ 47)%Z -> (4096 <= kf)%Z -> (kf + 1024 <= 2 ^ 47)%Z -> (4096 <= ls)%Z -> (ls + 80 <= 2 ^ 47)%Z ->
  store_ok SEGS M0 (Z_to_bv 64 datas) (Z.to_nat (W * h)) = true -> store_ok SEGS M0 (Z_to_bv 64 dd) (Z.to_nat (W * h)) = true ->
  ap_rds M0 kx kf ls W h linesf datak -> ap_apart dd (W * h) kx kf ls W h linesf datak ->
  rdn SEGS M0 (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 w) -> rdn SEGS M0 (Z_to_bv 64 (s - 96)) 4 = Some (Z_to_le_bytes 4 h) ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 10 = Z_to_bv 64 i -> getr regs 16 = Z_to_bv 64 w -> getr regs 9 = Z_to_bv 64 (datas + W * i) -> getr regs 18 = Z_to_bv 64 (dd + W * i) ->
  getr regs 20 = Z_to_bv 64 W -> getr regs 21 = Z_to_bv 64 W -> getr regs 22 = Z_to_bv 64 1 ->
  getr regs 23 = Z_to_bv 64 kx -> getr regs 24 = Z_to_bv 64 kf -> getr regs 25 = Z_to_bv 64 ls ->
  regs_agree (fun r => In r API) regs0 regs -> ap_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e120 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2e25c : word) M' rom /\ frm_zero cs' /\ rinv [(dd, (W * h)%Z)] M0 M' /\
                regs_agree (fun r => In r API) regs0 regs' /\ ap_fp fr0 fr').
