Lemma ap_B2 : forall fr cs regs (M : word -> option byte) (s w wpls wpld : Z),
  frm_zero cs -> (4096 + 96 <= s <= 2 ^ 47)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= wpls <= 20000)%Z -> (0 <= wpld <= 20000)%Z ->
  rdn SEGS M (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 w) ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 20 = Z_to_bv 64 wpls -> getr regs 21 = Z_to_bv 64 wpld ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e0ec : word) M rom)
    (fun fin => exists fr' cs' regs', fin = @mkst (mkFP fr' cs') regs' (0x2e120 : word) M rom /\ frm_zero cs' /\
                getr regs' 16 = Z_to_bv 64 w /\ getr regs' 20 = Z_to_bv 64 (4 * wpls) /\ getr regs' 21 = Z_to_bv 64 (4 * wpld) /\
                regs_agree (fun r => In r [12; 16; 20; 21]%bv) regs regs' /\ ap_fp fr fr').
